using System.ComponentModel.DataAnnotations;using Essco.Application.HumanResources;using Essco.Application.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Employees;
[Authorize(Policy=Permissions.Payroll)]public sealed class EditModel(EmployeeService service):PageModel
{[BindProperty]public Form Input{get;set;}=new();[BindProperty]public string?OriginalIdentification{get;set;}public bool IsNew=>string.IsNullOrWhiteSpace(OriginalIdentification);public IReadOnlyList<string>Positions=>EmployeeCatalog.Positions;public IReadOnlyList<string>Categories=>EmployeeCatalog.Categories;
 public async Task<IActionResult>OnGetAsync(string?id,CancellationToken t){if(string.IsNullOrWhiteSpace(id)){Input.HireDate=DateOnly.FromDateTime(DateTime.Today);Input.Active=true;return Page();}var file=await service.GetAsync(id,t);if(file is null)return NotFound();var e=file.Employee;OriginalIdentification=e.Identification;Input=new(){Identification=e.Identification,Code=e.Code,Name=e.Name,Position=e.Position,Salary=e.Salary,HireDate=e.HireDate,Active=e.Active,Route=e.Route,Email=e.Email,BankAccount=e.BankAccount,CollaboratorId=e.CollaboratorId,LedgerAccount=e.LedgerAccount,Category=e.Category,VacationEarned=e.VacationEarned,VacationUsed=e.VacationUsed,VacationPending=e.VacationPending};return Page();}
 public async Task<IActionResult>OnPostAsync(CancellationToken t){if(!ModelState.IsValid)return Page();var f=Input;var result=await service.SaveAsync(OriginalIdentification,new(f.Identification!,f.Code!,f.Name!,f.Position??"",f.Salary,f.HireDate,f.Active,f.Route??"",f.Email??"",f.Phone1??"",f.Phone2??"",f.BankAccount??"",f.CollaboratorId??"",f.LedgerAccount??"",f.Category??"",f.VacationEarned,f.VacationUsed,f.VacationPending),t);if(!result.Succeeded){ModelState.AddModelError("",result.Error!);return Page();}return RedirectToPage("Detail",new{id=f.Identification});}
 public sealed class Form{[Required,Display(Name="Cédula")]public string?Identification{get;set;}[Required,Display(Name="Código")]public string?Code{get;set;}[Required,Display(Name="Nombre completo")]public string?Name{get;set;}[Display(Name="Puesto")]public string?Position{get;set;}[Range(0,double.MaxValue),Display(Name="Salario")]public decimal Salary{get;set;}[Display(Name="Fecha de ingreso")]public DateOnly HireDate{get;set;}[Display(Name="Estado")]public bool Active{get;set;}[Display(Name="Ruta")]public string?Route{get;set;}[EmailAddress,Display(Name="Correo electrónico")]public string?Email{get;set;}[Display(Name="Teléfono principal")]public string?Phone1{get;set;}[Display(Name="Teléfono alterno")]public string?Phone2{get;set;}[Display(Name="Cuenta bancaria")]public string?BankAccount{get;set;}[Display(Name="Id. colaborador")]public string?CollaboratorId{get;set;}[Display(Name="Cuenta contable")]public string?LedgerAccount{get;set;}[Display(Name="Categoría")]public string?Category{get;set;}[Range(0,double.MaxValue),Display(Name="Ganadas")]public decimal VacationEarned{get;set;}[Range(0,double.MaxValue),Display(Name="Consumidas")]public decimal VacationUsed{get;set;}[Range(0,double.MaxValue),Display(Name="Pendientes")]public decimal VacationPending{get;set;}}
}
